package com.fethica.downloadskit.sample.fixtures

/**
 * The three files the sample downloads, generated by [WavFixture]: no recording and no
 * third-party audio, so they fall under this repository's own licence.
 *
 * Each is a valid WAV file: the canonical 44-byte RIFF/WAVE header (PCM, mono, 8000 Hz,
 * 16-bit little-endian), one second of sine tone at amplitude 4000 (about -18 dBFS) with
 * a -1..2 dither from a xorshift64 generator (shifts 13, 7, 17) seeded per fixture, then
 * silence up to the exact size. The sine goes through `StrictMath`, so the bytes are the
 * same on a JVM and on a phone.
 *
 * | Name | Path | Bytes | Tone | Seed | SHA-256 |
 * | --- | --- | --- | --- | --- | --- |
 * | tone-small | /fixtures/tone-small.wav | 65,536 | 440 Hz | 0x5EED0001 | f15c2a9e666ff4032681a9f1120c544c2dfbdc17b42291af0fd99d489c2d1693 |
 * | tone-medium | /fixtures/tone-medium.wav | 262,144 | 660 Hz | 0x5EED0002 | 785f16552b64ce827a6ed17bcc6681f125ceca763403d17089f98adcb7585335 |
 * | tone-large | /fixtures/tone-large.wav | 1,048,576 | 880 Hz | 0x5EED0003 | 6acb03de3aade2b2c14e9cadaf364629cf69ea3c70727eb9e1d185483882e34e |
 *
 * [PINNED_SHA256] holds the same hashes. A unit test regenerates every file and fails if
 * one moves, so a generator change must update this table in the same commit, and the
 * diagnostics panel shows the pinned value next to the hash computed on the device.
 */
public object FixtureCatalog {

    public val small: WavFixture = WavFixture(
        name = "tone-small",
        seed = 0x5EED_0001L,
        sizeBytes = 64 * 1024,
        toneHz = 440,
        toneMillis = 1_000,
    )

    public val medium: WavFixture = WavFixture(
        name = "tone-medium",
        seed = 0x5EED_0002L,
        sizeBytes = 256 * 1024,
        toneHz = 660,
        toneMillis = 1_000,
    )

    public val large: WavFixture = WavFixture(
        name = "tone-large",
        seed = 0x5EED_0003L,
        sizeBytes = 1024 * 1024,
        toneHz = 880,
        toneMillis = 1_000,
    )

    public val all: List<WavFixture> = listOf(small, medium, large)

    /** The SHA-256 of each fixture by name, as listed in the table above. */
    public val PINNED_SHA256: Map<String, String> = mapOf(
        "tone-small" to "f15c2a9e666ff4032681a9f1120c544c2dfbdc17b42291af0fd99d489c2d1693",
        "tone-medium" to "785f16552b64ce827a6ed17bcc6681f125ceca763403d17089f98adcb7585335",
        "tone-large" to "6acb03de3aade2b2c14e9cadaf364629cf69ea3c70727eb9e1d185483882e34e",
    )

    public fun byName(name: String): WavFixture? = all.firstOrNull { it.name == name }

    public fun byPath(path: String): WavFixture? = all.firstOrNull { it.path == path }
}
